DELIMITER $$
--
-- Procedimientos
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_crear_tareas_individuales` ()   BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE user_id INT;
    DECLARE partido_id INT;
    DECLARE partido_fecha DATETIME;
    DECLARE equipo_local VARCHAR(100);
    DECLARE equipo_visitante VARCHAR(100);
    
    -- Cursor para usuarios activos
    DECLARE user_cursor CURSOR FOR 
    SELECT id_usuario FROM usuario WHERE estado_conexion != 'desconectado';
    
    -- Cursor para partidos futuros (próximos 3 días)
    DECLARE partido_cursor CURSOR FOR 
    SELECT id_partido, fecha, equipo_local, equipo_visitante 
    FROM partido 
    WHERE fecha BETWEEN NOW() AND DATE_ADD(NOW(), INTERVAL 3 DAY);
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    -- Crear tareas de pronóstico para partidos futuros
    OPEN partido_cursor;
    partido_loop: LOOP
        FETCH partido_cursor INTO partido_id, partido_fecha, equipo_local, equipo_visitante;
        IF done THEN
            LEAVE partido_loop;
        END IF;
        
        -- Para cada partido, crear tarea de pronóstico para todos los usuarios
        OPEN user_cursor;
        SET done = FALSE;
        user_loop: LOOP
            FETCH user_cursor INTO user_id;
            IF done THEN
                LEAVE user_loop;
            END IF;
            
            -- Verificar si ya existe la tarea
            IF NOT EXISTS (
                SELECT 1 FROM tarea 
                WHERE id_partido = partido_id 
                AND tipo = 'pronostico' 
                AND scope = 'individual'
                AND creado_por IS NULL
            ) THEN
                INSERT INTO tarea (
                    id_grupo, id_partido, nombre, descripcion, tipo, 
                    fecha_limite, puntos, estado, scope
                ) VALUES (
                    NULL, partido_id, 
                    CONCAT('Pronóstico: ', equipo_local, ' vs ', equipo_visitante),
                    'Realiza tu pronóstico del marcador exacto y el primer goleador.',
                    'pronostico', partido_fecha, 5, 'Pendiente', 'individual'
                );
            END IF;
        END LOOP user_loop;
        CLOSE user_cursor;
        SET done = FALSE;
    END LOOP partido_loop;
    CLOSE partido_cursor;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_login_usuario` (IN `p_correo` VARCHAR(150), IN `p_contraseña` VARCHAR(255))   BEGIN
    DECLARE v_id INT;

    -- Buscar si existe usuario
    SELECT id_usuario INTO v_id
    FROM Usuario
    WHERE correo = p_correo 
      AND contraseña = p_contraseña
    LIMIT 1;

    IF v_id IS NOT NULL THEN
        -- Cambiar estado a en línea
        UPDATE Usuario 
        SET estado_conexion = 'en_linea'
        WHERE id_usuario = v_id;

        -- Retornar datos
        SELECT id_usuario, nombre, correo, estado_conexion, nivel, puntos_totales, es_admin
        FROM Usuario
        WHERE id_usuario = v_id;
    ELSE
        -- Usuario no encontrado
        SELECT NULL AS id_usuario;
    END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_obtener_usuario` (IN `p_correo` VARCHAR(150))   BEGIN
    SELECT id_usuario, nombre, correo, contraseña, estado_conexion, nivel, puntos_totales, es_admin
    FROM Usuario
    WHERE correo = p_correo
    LIMIT 1;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_usuario` (IN `p_nombre` VARCHAR(100), IN `p_correo` VARCHAR(150), IN `p_contraseña` VARCHAR(255), IN `p_pais` VARCHAR(100), IN `p_foto` MEDIUMBLOB)   BEGIN
    INSERT INTO Usuario (nombre, correo, contraseña, pais, foto_perfil)
    VALUES (p_nombre, p_correo, p_contraseña, p_pais, p_foto);
END$$

DELIMITER ;

