--
-- Disparadores `partido`
--
DELIMITER $$
CREATE TRIGGER `after_partido_creado` AFTER INSERT ON `partido` FOR EACH ROW BEGIN
    -- Crear tarea de pronóstico para CADA usuario
    INSERT INTO tarea (id_usuario, id_partido, nombre, descripcion, tipo, fecha_limite, puntos, estado, scope)
    SELECT u.id_usuario, NEW.id_partido,
           CONCAT('Pronóstico: ', NEW.equipo_local, ' vs ', NEW.equipo_visitante),
           'Haz tu pronóstico del resultado final de este partido.',
           'pronostico', NEW.fecha, 5, 'Pendiente', 'individual'
    FROM usuario u;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_partido_finalizado` AFTER UPDATE ON `partido` FOR EACH ROW BEGIN
    -- Si se actualiza el resultado_final (partido terminado)
    IF NEW.resultado_final IS NOT NULL AND OLD.resultado_final IS NULL THEN
        -- Crear tarea de resumen para CADA usuario
        INSERT INTO tarea (
            id_usuario, id_partido, nombre, descripcion, tipo, 
            fecha_limite, puntos, estado, scope
        )
        SELECT u.id_usuario, NEW.id_partido,
            CONCAT('Resumen: ', NEW.equipo_local, ' vs ', NEW.equipo_visitante),
            'Redacta un resumen analítico del partido.',
            'resumen', DATE_ADD(NOW(), INTERVAL 24 HOUR), 3, 'Pendiente', 'individual'
        FROM usuario u;
        
        -- Crear tarea de jugador clave para CADA usuario
        INSERT INTO tarea (
            id_usuario, id_partido, nombre, descripcion, tipo, 
            fecha_limite, puntos, estado, scope
        )
        SELECT u.id_usuario, NEW.id_partido,
            CONCAT('Jugador Clave: ', NEW.equipo_local, ' vs ', NEW.equipo_visitante),
            'Identifica al jugador clave del partido y justifica tu elección.',
            'jugador', DATE_ADD(NOW(), INTERVAL 24 HOUR), 2, 'Pendiente', 'individual'
        FROM usuario u;
    END IF;
END
$$
DELIMITER ;

